import { api } from "../lib/api";
import type { OrgType } from "./users";

// Reports generated by customers — docs/ADMIN_PANEL.md §7 (platform.read). Read-only.

export type ReportType = "rank_tracker" | "gbp_audit" | "competitor_analysis" | "citation" | "reputation" | "full";
export type ReportStatus = "queued" | "generating" | "ready" | "failed" | "expired" | "archived";

export const REPORT_TYPES: ReportType[] = ["rank_tracker", "gbp_audit", "competitor_analysis", "citation", "reputation", "full"];
export const REPORT_STATUSES: ReportStatus[] = ["queued", "generating", "ready", "failed", "expired", "archived"];

export const REPORT_TYPE_LABELS: Record<ReportType, string> = {
  rank_tracker: "Rank tracker",
  gbp_audit: "GBP audit",
  competitor_analysis: "Competitor analysis",
  citation: "Citations",
  reputation: "Reputation",
  full: "Full report",
};

export type ReportRow = {
  report_id: string;
  type: ReportType;
  sections: string[];
  status: ReportStatus;
  trigger: "manual" | "schedule";
  schedule_id: string | null;
  location: { location_id: string; name: string | null; deleted?: boolean } | null;
  client: { client_id: string; name: string | null } | null;
  range: string | null;
  run_id: string | null;
  run_at: string | null;
  pdf: { bytes: number; pages: number } | null;
  failure_reason: string | null;
  created_at: string;
  generated_at: string | null;
  expires_at: string | null;
  archived_at: string | null;
  organization?: { id: string; name: string | null; type: OrgType | null };
};

export type HeatmapBucket = "pack" | "visible" | "low" | "invisible" | "not_found" | "error";

export type ReportBlock =
  | { kind: "heading"; level: number; text: string }
  | { kind: "paragraph"; text: string; muted?: boolean }
  | { kind: "kpis"; items: { label: string; value: string; sub?: string; tone?: "good" | "bad" | "neutral" }[] }
  | {
      kind: "table";
      title?: string;
      columns: { label: string; weight?: number; align?: "left" | "right" | "center" }[];
      rows: (string | number | null)[][];
      highlight?: number[];
    }
  | { kind: "line_chart"; title?: string; points: { label: string; value: number | null }[]; lower_is_better?: boolean }
  | {
      kind: "heatmap";
      title?: string;
      size: number;
      cells: { row: number; col: number; text: string; bucket: HeatmapBucket }[];
      max_rank?: number;
    }
  | { kind: "list"; title?: string; items: string[] }
  | { kind: "unavailable"; title?: string; message: string }
  | { kind: "quotes"; items: { text: string; meta: string; link: string | null }[] }
  | { kind: "page_break" };

export type ReportDetail = {
  report: ReportRow;
  snapshot: unknown;
  document: {
    title: string;
    period?: string | null;
    generated_at?: string | null;
    branding?: { name?: string | null; primary_color?: string | null } | null;
    blocks: ReportBlock[];
    attribution?: string | null;
  } | null;
  attribution?: { provider: string; text: string } | null;
};

export type ReportListQuery = {
  organization_id?: string;
  location_id?: string;
  type?: ReportType;
  status?: ReportStatus;
  trigger?: "manual" | "schedule";
  from?: string;
  to?: string;
  page?: number;
  limit?: number;
};

export const reportsApi = {
  list: (query: ReportListQuery, signal?: AbortSignal) =>
    api<{ reports: ReportRow[]; page: number; limit: number; total: number }>("/admin/reports", { query, signal }),
  get: (reportId: string, signal?: AbortSignal) => api<ReportDetail>(`/admin/reports/${reportId}`, { signal }),
  pdfPath: (reportId: string) => `/admin/reports/${reportId}/pdf`,
};

/** What a 409 on the PDF means. */
export const REPORT_PDF_REASONS: Record<string, string> = {
  not_ready: "The PDF isn't ready yet.",
  expired: "This report has expired; its PDF was removed.",
  file_missing: "The PDF file is missing on the server.",
};
